def fibonacci(n):
"""
Return the nth Fibonacci number using an iterative approach.
fibonacci(0) -> 0
fibonacci(1) -> 1
"""
if n < 0:
raise ValueError("n must be a non‑negative integer")
a, b = 0, 1
for _ in range(n):
a, b = b, a + b
return a
